begin;

update public.subscription_plans set monthly_price_pence=5900,annual_price_pence=59000,stripe_monthly_price_id=null,stripe_annual_price_id=null,updated_at=now() where code='professional';
update public.subscription_plans set monthly_price_pence=9900,annual_price_pence=99000,stripe_monthly_price_id=null,stripe_annual_price_id=null,updated_at=now() where code='growth';

insert into public.restaurant_team_roles(restaurant_id,key,name,permissions,is_system)
select r.id,v.key,v.name,v.permissions,true from public.restaurants r cross join(values
 ('manager','Manager','["orders:view","orders:manage","menu:view","menu:manage","customers:view","marketing:view","analytics:view","team:view"]'::jsonb),
 ('staff','Staff','["orders:view","orders:manage","menu:view"]'::jsonb),
 ('kitchen','Kitchen','["orders:view","orders:manage","kds:view"]'::jsonb))v(key,name,permissions)
on conflict(restaurant_id,key) do nothing;

create or replace function private.ensure_restaurant_team_roles() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.restaurant_team_roles(restaurant_id,key,name,permissions,is_system) values(new.id,'manager','Manager','["orders:view","orders:manage","menu:view","menu:manage","customers:view","marketing:view","analytics:view","team:view"]'::jsonb,true),(new.id,'staff','Staff','["orders:view","orders:manage","menu:view"]'::jsonb,true),(new.id,'kitchen','Kitchen','["orders:view","orders:manage","kds:view"]'::jsonb,true) on conflict(restaurant_id,key) do nothing;return new;end$$;
drop trigger if exists ensure_restaurant_team_roles on public.restaurants;
create trigger ensure_restaurant_team_roles after insert on public.restaurants for each row execute function private.ensure_restaurant_team_roles();

create or replace function public.create_restaurant_team_invite(p_email text,p_role public.restaurant_member_role default 'staff',p_custom_role_id uuid default null,p_permissions jsonb default '[]'::jsonb,p_expires_days integer default 7) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;token text;token_digest text;invite_id uuid;lim bigint;used bigint;pending bigint;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and role='owner' and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant owner access required' using errcode='42501';end if;if p_email is null or position('@' in p_email)<2 then raise exception 'Valid email required';end if;if jsonb_typeof(p_permissions)<>'array' then raise exception 'Permissions must be an array';end if;if p_expires_days<1 or p_expires_days>30 then raise exception 'Invite expiry must be 1 to 30 days';end if;if p_custom_role_id is not null and not exists(select 1 from public.restaurant_team_roles where id=p_custom_role_id and restaurant_id=rid) then raise exception 'Role not found' using errcode='42501';end if;lim:=coalesce((private.restaurant_plan_feature(rid,'max_team_members')#>>'{}')::bigint,0);used:=private.restaurant_usage_value(rid,'max_team_members');select count(*) into pending from public.restaurant_team_invites where restaurant_id=rid and accepted_at is null and revoked_at is null and expires_at>now();if lim<>-1 and used+pending+1>lim then raise exception 'Team member plan limit reached' using errcode='42501';end if;if exists(select 1 from public.restaurant_members rm join auth.users u on u.id=rm.user_id where rm.restaurant_id=rid and lower(u.email)=lower(trim(p_email))) then raise exception 'This user is already on the team';end if;update public.restaurant_team_invites set revoked_at=now() where restaurant_id=rid and lower(email)=lower(trim(p_email)) and accepted_at is null and revoked_at is null;token:=encode(gen_random_bytes(32),'hex');token_digest:=encode(digest(token,'sha256'),'hex');insert into public.restaurant_team_invites(restaurant_id,email,role,custom_role_id,permissions,token_hash,invited_by,expires_at) values(rid,lower(trim(p_email)),p_role,p_custom_role_id,p_permissions,token_digest,(select auth.uid()),now()+make_interval(days=>p_expires_days)) returning id into invite_id;insert into public.restaurant_team_activity(restaurant_id,actor_user_id,action,details) values(rid,(select auth.uid()),'invite_created',jsonb_build_object('invite_id',invite_id,'email',lower(trim(p_email)),'role',p_role));return jsonb_build_object('id',invite_id,'token',token,'email',lower(trim(p_email)),'expires_at',now()+make_interval(days=>p_expires_days));end$$;
create or replace function public.revoke_restaurant_team_invite(p_invite_id uuid) returns void language plpgsql security definer set search_path='' as $$declare rid uuid;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and role='owner' and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant owner access required' using errcode='42501';end if;update public.restaurant_team_invites set revoked_at=now() where id=p_invite_id and restaurant_id=rid and accepted_at is null and revoked_at is null;if not found then raise exception 'Pending invite not found';end if;insert into public.restaurant_team_activity(restaurant_id,actor_user_id,action,details) values(rid,(select auth.uid()),'invite_revoked',jsonb_build_object('invite_id',p_invite_id));end$$;
create or replace function public.manage_restaurant_team_role(p_action text,p_role_id uuid default null,p_key text default null,p_name text default null,p_permissions jsonb default null) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;row_result public.restaurant_team_roles%rowtype;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and role='owner' and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant owner access required' using errcode='42501';end if;if p_action='create' then if p_key is null or p_key!~'^[a-z0-9_-]+$' or p_name is null then raise exception 'Role key and name are required';end if;if p_permissions is null or jsonb_typeof(p_permissions)<>'array' then raise exception 'Permissions must be an array';end if;insert into public.restaurant_team_roles(restaurant_id,key,name,permissions,is_system) values(rid,p_key,p_name,p_permissions,false) returning * into row_result;elsif p_action='update' then update public.restaurant_team_roles set name=coalesce(p_name,name),permissions=coalesce(p_permissions,permissions),updated_at=now() where id=p_role_id and restaurant_id=rid returning * into row_result;elsif p_action='delete' then if exists(select 1 from public.restaurant_team_roles where id=p_role_id and restaurant_id=rid and is_system) then raise exception 'System roles cannot be deleted';end if;delete from public.restaurant_team_roles where id=p_role_id and restaurant_id=rid returning * into row_result;else raise exception 'Unsupported role action';end if;if row_result.id is null then raise exception 'Role not found';end if;insert into public.restaurant_team_activity(restaurant_id,actor_user_id,action,details) values(rid,(select auth.uid()),'role_'||p_action,jsonb_build_object('role_id',row_result.id,'key',row_result.key));return to_jsonb(row_result);end$$;

create or replace function public.admin_create_subscription_plan(p_code text,p_name text,p_monthly_price_pence integer,p_annual_price_pence integer default null,p_trial_days integer default 14,p_setup_fee_pence integer default 0,p_is_public boolean default true,p_custom_pricing boolean default false,p_features jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare plan public.subscription_plans%rowtype;begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_code!~'^[a-z0-9_-]+$' or p_name is null or trim(p_name)='' then raise exception 'Valid plan code and name required';end if;if p_monthly_price_pence<0 or p_annual_price_pence<0 or p_setup_fee_pence<0 then raise exception 'Plan prices cannot be negative';end if;insert into public.subscription_plans(code,name,monthly_price_pence,annual_price_pence,trial_days,setup_fee_pence,is_public,custom_pricing,features,sort_order) values(p_code,trim(p_name),p_monthly_price_pence,p_annual_price_pence,p_trial_days,p_setup_fee_pence,p_is_public,p_custom_pricing,p_features,coalesce((select max(sort_order)+10 from public.subscription_plans),10)) returning * into plan;insert into public.platform_admin_audit_log(actor_user_id,action,target_type,target_id,details) values((select auth.uid()),'subscription.plan.create','subscription_plan',plan.id::text,jsonb_build_object('code',p_code,'name',p_name));return to_jsonb(plan)-'stripe_monthly_price_id'-'stripe_annual_price_id';end$$;
create or replace function public.admin_manage_subscription_plan(p_plan_id uuid,p_patch jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare updated public.subscription_plans%rowtype;begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_patch?'features' and jsonb_typeof(p_patch->'features')<>'object' then raise exception 'features must be an object';end if;update public.subscription_plans set name=coalesce(p_patch->>'name',name),description=coalesce(p_patch->>'description',description),monthly_price_pence=coalesce((p_patch->>'monthly_price_pence')::integer,monthly_price_pence),annual_price_pence=case when p_patch?'annual_price_pence' then(p_patch->>'annual_price_pence')::integer else annual_price_pence end,trial_days=coalesce((p_patch->>'trial_days')::integer,trial_days),setup_fee_pence=coalesce((p_patch->>'setup_fee_pence')::integer,setup_fee_pence),is_active=coalesce((p_patch->>'is_active')::boolean,is_active),is_public=coalesce((p_patch->>'is_public')::boolean,is_public),supports_monthly=coalesce((p_patch->>'supports_monthly')::boolean,supports_monthly),supports_annual=coalesce((p_patch->>'supports_annual')::boolean,supports_annual),custom_pricing=coalesce((p_patch->>'custom_pricing')::boolean,custom_pricing),features=case when p_patch?'features' then p_patch->'features' else features end,metadata=case when p_patch?'metadata' then metadata||p_patch->'metadata' else metadata end,stripe_monthly_price_id=case when p_patch?'monthly_price_pence' then null else stripe_monthly_price_id end,stripe_annual_price_id=case when p_patch?'annual_price_pence' then null else stripe_annual_price_id end,updated_at=now() where id=p_plan_id returning * into updated;if updated.id is null then raise exception 'Plan not found';end if;insert into public.platform_admin_audit_log(actor_user_id,action,target_type,target_id,details) values((select auth.uid()),'subscription.plan.update','subscription_plan',updated.id::text,p_patch);return to_jsonb(updated)-'stripe_monthly_price_id'-'stripe_annual_price_id';end$$;
create or replace function public.admin_assign_restaurant_plan(p_restaurant_id uuid,p_plan_id uuid,p_billing_interval text default 'monthly',p_custom_price_pence integer default null) returns uuid language plpgsql security definer set search_path='' as $$declare sid uuid;begin if not private.platform_admin_has_permission('finance:manage') then raise exception 'Finance management access required' using errcode='42501';end if;if p_billing_interval not in('monthly','annual') then raise exception 'Invalid billing interval';end if;if not exists(select 1 from public.subscription_plans where id=p_plan_id and is_active) then raise exception 'Plan not found';end if;insert into public.restaurant_subscriptions(restaurant_id,plan_id,status,billing_interval,custom_price_pence,updated_at) values(p_restaurant_id,p_plan_id,'active',p_billing_interval,p_custom_price_pence,now()) on conflict(restaurant_id) do update set plan_id=excluded.plan_id,status='active',billing_interval=excluded.billing_interval,custom_price_pence=excluded.custom_price_pence,cancel_at_period_end=false,cancelled_at=null,ended_at=null,updated_at=now() returning id into sid;insert into public.restaurant_subscription_events(restaurant_id,subscription_id,event_type,details) values(p_restaurant_id,sid,'admin_plan_assigned',jsonb_build_object('plan_id',p_plan_id,'billing_interval',p_billing_interval,'custom_price_pence',p_custom_price_pence,'admin_user_id',(select auth.uid())));insert into public.platform_admin_audit_log(actor_user_id,action,target_type,target_id,details) values((select auth.uid()),'subscription.assign','restaurant',p_restaurant_id::text,jsonb_build_object('plan_id',p_plan_id,'billing_interval',p_billing_interval,'custom_price_pence',p_custom_price_pence));return sid;end$$;

create or replace function public.get_restaurant_billing_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$declare rid uuid;result jsonb;has_subscription boolean;begin select restaurant_id into rid from public.restaurant_members where user_id=(select auth.uid()) and status='active' order by created_at limit 1;if rid is null then raise exception 'Restaurant membership not found' using errcode='42501';end if;select exists(select 1 from public.restaurant_subscriptions where restaurant_id=rid) into has_subscription;select jsonb_build_object('restaurant_id',rid,'subscription',case when s.id is null then null else jsonb_build_object('id',s.id,'status',s.status,'billing_interval',s.billing_interval,'trial_ends_at',s.trial_ends_at,'current_period_start',s.current_period_start,'current_period_end',s.current_period_end,'cancel_at_period_end',s.cancel_at_period_end,'grace_period_ends_at',s.grace_period_ends_at,'paused_at',s.paused_at,'resume_at',s.resume_at,'comped_until',s.comped_until,'custom_price_pence',s.custom_price_pence,'plan',to_jsonb(p)-'stripe_monthly_price_id'-'stripe_annual_price_id') end,'plans',coalesce((select jsonb_agg(to_jsonb(sp)-'stripe_monthly_price_id'-'stripe_annual_price_id' order by sp.sort_order) from public.subscription_plans sp where sp.is_active and(sp.is_public or sp.id=s.plan_id)),'[]'::jsonb),'usage',case when has_subscription then public.get_restaurant_subscription_usage() else '{}'::jsonb end,'invoices',coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc) from(select * from public.restaurant_subscription_invoices where restaurant_id=rid order by created_at desc limit 24)i),'[]'::jsonb),'credits',coalesce((select jsonb_agg(to_jsonb(c) order by c.created_at desc) from(select * from public.restaurant_billing_credits where restaurant_id=rid order by created_at desc limit 24)c),'[]'::jsonb),'enterprise',coalesce((select to_jsonb(e) from public.restaurant_enterprise_settings e where e.restaurant_id=rid),'{}'::jsonb)) into result from(select rid)x left join public.restaurant_subscriptions s on s.restaurant_id=rid left join public.subscription_plans p on p.id=s.plan_id;return result;end$$;

create or replace function private.enforce_restaurant_plan_limit_trigger() returns trigger language plpgsql security definer set search_path='' as $$declare rid uuid;feature text;lim bigint;used bigint;activating boolean:=true;begin rid:=new.restaurant_id;if tg_table_name='restaurant_locations' then feature:='max_locations';activating:=new.is_active and(tg_op='INSERT' or not coalesce(old.is_active,false));elsif tg_table_name='restaurant_members' then feature:='max_team_members';activating:=new.status='active' and(tg_op='INSERT' or old.status<>'active');elsif tg_table_name='restaurant_printers' then feature:='max_printers';activating:=new.is_active and(tg_op='INSERT' or not coalesce(old.is_active,false));elsif tg_table_name='restaurant_kitchen_displays' then feature:='max_kitchen_displays';activating:=new.is_active and(tg_op='INSERT' or not coalesce(old.is_active,false));elsif tg_table_name='restaurant_marketing_campaigns' then feature:='max_campaigns';activating:=tg_op='INSERT';elsif tg_table_name='restaurant_marketing_automations' then feature:='max_automations';activating:=tg_op='INSERT';else return new;end if;if not activating then return new;end if;if not exists(select 1 from public.restaurant_subscriptions where restaurant_id=rid) then return new;end if;lim:=coalesce((private.restaurant_plan_feature(rid,feature)#>>'{}')::bigint,0);used:=private.restaurant_usage_value(rid,feature);if lim<>-1 and used+1>lim then raise exception 'Plan limit reached for % (% of % used)',feature,used,lim using errcode='42501';end if;return new;end$$;
drop trigger if exists enforce_location_plan_limit on public.restaurant_locations;create trigger enforce_location_plan_limit before insert or update of is_active on public.restaurant_locations for each row execute function private.enforce_restaurant_plan_limit_trigger();
drop trigger if exists enforce_member_plan_limit on public.restaurant_members;create trigger enforce_member_plan_limit before insert or update of status on public.restaurant_members for each row execute function private.enforce_restaurant_plan_limit_trigger();
drop trigger if exists enforce_printer_plan_limit on public.restaurant_printers;create trigger enforce_printer_plan_limit before insert or update of is_active on public.restaurant_printers for each row execute function private.enforce_restaurant_plan_limit_trigger();
drop trigger if exists enforce_kds_plan_limit on public.restaurant_kitchen_displays;create trigger enforce_kds_plan_limit before insert or update of is_active on public.restaurant_kitchen_displays for each row execute function private.enforce_restaurant_plan_limit_trigger();
drop trigger if exists enforce_campaign_plan_limit on public.restaurant_marketing_campaigns;create trigger enforce_campaign_plan_limit before insert on public.restaurant_marketing_campaigns for each row execute function private.enforce_restaurant_plan_limit_trigger();
drop trigger if exists enforce_automation_plan_limit on public.restaurant_marketing_automations;create trigger enforce_automation_plan_limit before insert on public.restaurant_marketing_automations for each row execute function private.enforce_restaurant_plan_limit_trigger();

create table if not exists public.restaurant_subscription_notification_deliveries(id bigint generated always as identity primary key,event_id bigint not null references public.restaurant_subscription_events(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,channel text not null check(channel in('email','in_app')),status text not null default 'pending' check(status in('pending','sent','failed','skipped')),provider_message_id text,last_error text,attempts integer not null default 0,sent_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_id,user_id,channel));
alter table public.restaurant_subscription_notification_deliveries enable row level security;revoke all on public.restaurant_subscription_notification_deliveries from public,anon,authenticated;create policy subscription_notification_delivery_admin_read on public.restaurant_subscription_notification_deliveries for select to authenticated using(private.platform_admin_has_permission('finance:view'));grant select on public.restaurant_subscription_notification_deliveries to authenticated;
create or replace function public.prepare_subscription_notifications(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;insert into public.restaurant_subscription_events(restaurant_id,subscription_id,event_type,details) select s.restaurant_id,s.id,'trial_ending',jsonb_build_object('trial_ends_at',s.trial_ends_at) from public.restaurant_subscriptions s where s.status='trialing' and s.trial_ends_at between now() and now()+interval '3 days' and not exists(select 1 from public.restaurant_subscription_events e where e.subscription_id=s.id and e.event_type='trial_ending' and e.details->>'trial_ends_at'=s.trial_ends_at::text);insert into public.restaurant_subscription_notification_deliveries(event_id,user_id,channel) select e.id,rm.user_id,'email' from public.restaurant_subscription_events e join public.restaurant_members rm on rm.restaurant_id=e.restaurant_id and rm.status='active' where e.event_type in('trial_ending','invoice_payment_failed','invoice_available','subscription_renewed','subscription_upgraded','subscription_downgraded','subscription_cancelled','subscription_resumed') on conflict(event_id,user_id,channel) do nothing;select coalesce(jsonb_agg(jsonb_build_object('delivery_id',d.id,'event_id',e.id,'event_type',e.event_type,'restaurant_id',e.restaurant_id,'user_id',d.user_id,'email',u.email,'restaurant_name',r.name,'details',e.details) order by d.created_at),'[]'::jsonb) into result from(select * from public.restaurant_subscription_notification_deliveries where channel='email' and status in('pending','failed') and attempts<5 order by created_at limit greatest(1,least(p_limit,500)))d join public.restaurant_subscription_events e on e.id=d.event_id join auth.users u on u.id=d.user_id join public.restaurants r on r.id=e.restaurant_id;return result;end$$;
create or replace function public.complete_subscription_notification(p_delivery_id bigint,p_succeeded boolean,p_provider_message_id text default null,p_error text default null) returns void language plpgsql security definer set search_path='' as $$begin if auth.role()<>'service_role' then raise exception 'Service role required' using errcode='42501';end if;update public.restaurant_subscription_notification_deliveries set status=case when p_succeeded then 'sent' else 'failed' end,provider_message_id=coalesce(p_provider_message_id,provider_message_id),last_error=case when p_succeeded then null else left(p_error,1000) end,attempts=attempts+1,sent_at=case when p_succeeded then now() else sent_at end,updated_at=now() where id=p_delivery_id;end$$;

revoke all on function public.create_restaurant_team_invite(text,public.restaurant_member_role,uuid,jsonb,integer),public.revoke_restaurant_team_invite(uuid),public.manage_restaurant_team_role(text,uuid,text,text,jsonb),public.admin_create_subscription_plan(text,text,integer,integer,integer,integer,boolean,boolean,jsonb),public.admin_manage_subscription_plan(uuid,jsonb),public.admin_assign_restaurant_plan(uuid,uuid,text,integer),public.prepare_subscription_notifications(integer),public.complete_subscription_notification(bigint,boolean,text,text) from public,anon,authenticated;
grant execute on function public.create_restaurant_team_invite(text,public.restaurant_member_role,uuid,jsonb,integer),public.revoke_restaurant_team_invite(uuid),public.manage_restaurant_team_role(text,uuid,text,text,jsonb) to authenticated;
grant execute on function public.admin_create_subscription_plan(text,text,integer,integer,integer,integer,boolean,boolean,jsonb),public.admin_manage_subscription_plan(uuid,jsonb),public.admin_assign_restaurant_plan(uuid,uuid,text,integer) to authenticated;
grant execute on function public.prepare_subscription_notifications(integer),public.complete_subscription_notification(bigint,boolean,text,text) to service_role;

commit;
